INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q15844352', 'Battle of Remich', 'The Battle of Remich was fought between Vikings and Frankish officials at Remich, Luxembourg, on April 11, 882. The Vikings were led by Godfrid and Sigfrid, while the Franks were led by Wala, the archbishop of Metz, Bertulf, the archbishop of Trier, and Adalhard, the Count of Metz.', 882, 4, 11, NULL, NULL, NULL, 'day', '11 April 882', 34, 'https://en.wikipedia.org/wiki/Battle_of_Remich'),
  ('Q815171', 'Siege of Luxembourg', 'The siege of Luxembourg, in which Louis XIV of France (husband of Maria Theresa of Spain) laid siege to the Spanish-controlled Fortress of Luxembourg from 27 April to 7 June 1684, was the most significant confrontation of the War of the Reunions between France and Spain. The action caused alarm among France''s neighbours and resulted in the formation of the League of Augsburg in 1686.', 1684, 4, 27, 1684, 6, 7, 'day', '27 April 1684 – 7 June 1684', 43, 'https://en.wikipedia.org/wiki/Siege_of_Luxembourg_(1684)'),
  ('Q904495', 'Siege of Luxembourg', 'The siege of Luxembourg was a siege by France of the Habsburg-held Fortress of Luxembourg that lasted from 1794 until 7 June 1795, during the French Revolutionary Wars. Although the French army failed to breach the walls of the city, which were renowned as amongst the best in the world, the fortress was forced to surrender after more than seven months.', 1794, 11, 22, 1795, 6, 7, 'day', '22 November 1794 – 7 June 1795', 50, 'https://en.wikipedia.org/wiki/Siege_of_Luxembourg_(1794%E2%80%931795)'),
  ('Q17015429', 'Revolution of 1848 in Luxembourg', 'The Revolution of 1848 in Luxembourg was part of the revolutionary wave which occurred across Europe in 1848. The Grand-Duchy of Luxembourg at that time was in personal union with the Kingdom of the Netherlands.', 1848, NULL, NULL, NULL, NULL, NULL, 'year', '1848', 30, 'https://en.wikipedia.org/wiki/Revolution_of_1848_in_Luxembourg'),
  ('Q6706220', 'Luxembourg Coup of 1856', 'The Luxembourg coup of 1856, also called the putsch of 1856, was a reactionary revision of Luxembourg''s constitution on 27 November 1856. Whilst not a true coup d''état or revolution, its detractors dubbed it a "royal coup", as the reigning Grand Duke of Luxembourg, William III, greatly expanded his powers, and the name has stuck.', 1856, 11, NULL, NULL, NULL, NULL, 'month', 'November 1856', 41, 'https://en.wikipedia.org/wiki/Luxembourg_coup_of_1856'),
  ('Q3119117', 'Ecuadorian–Peruvian War of 1857–1860', 'The First Ecuadorian–Peruvian War took place between 1857 and 1860. The conflict began when Ecuador attempted to sell Amazon basin land claimed by Peru in order to settle a debt with British creditors.', 1857, NULL, NULL, 1860, 1, 25, 'year', '1857 – 25 January 1860', 39, 'https://en.wikipedia.org/wiki/Ecuadorian%E2%80%93Peruvian_War_(1857%E2%80%931860)'),
  ('Q699765', 'Luxembourg Crisis', 'The Luxembourg Crisis (German: Luxemburgkrise; French: Crise luxembourgeoise) was a diplomatic dispute and confrontation in 1867 between France and Prussia over the political status of Luxembourg. The confrontation almost led to war between the two parties, but was peacefully resolved by the Treaty of London.', 1867, NULL, NULL, NULL, NULL, NULL, 'year', '1867', 60, 'https://en.wikipedia.org/wiki/Luxembourg_Crisis'),
  ('Q153214', 'German occupation of Luxembourg during World War I', 'From 2 August 1914 until the end of World War I on 11 November 1918, the Grand Duchy of Luxembourg was under full occupation by the German Empire. The German government justified the occupation by citing the need to support their armies in neighbouring France, although many Luxembourgers, past and present, have interpreted German actions otherwise.', 1914, 8, NULL, 1918, 11, 11, 'month', 'August 1914 – 11 November 1918', 59, 'https://en.wikipedia.org/wiki/German_occupation_of_Luxembourg_during_World_War_I'),
  ('Q151340', 'Battle of France', 'The Battle of France (French: Bataille de France, 10 May – 25 June 1940), also known as the Fall of France, was the German invasion of the Low Countries (Belgium, Luxembourg and the Netherlands) and France during the Second World War. The plan for the invasion of the Low Countries and France was called Fall Gelb (Case Yellow or the Manstein plan).', 1940, 5, 10, 1940, 6, 25, 'day', '10 May 1940 – 25 June 1940', 82, 'https://en.wikipedia.org/wiki/Battle_of_France'),
  ('Q13435464', 'German invasion of Luxembourg', 'The German invasion of Luxembourg was part of Case Yellow (German: Fall Gelb), the German invasion of the Low Countries—Belgium, Luxembourg and the Netherlands—and France during World War II. The battle began on 10 May 1940 and lasted just one day. Facing only light resistance, German troops quickly occupied Luxembourg.', 1940, 5, 10, NULL, NULL, NULL, 'day', '10 May 1940', 61, 'https://en.wikipedia.org/wiki/German_invasion_of_Luxembourg'),
  ('Q151018', 'Battle of the Bulge', 'The Battle of the Bulge, also known as the Ardennes Offensive and referred to by the Germans as Unternehmen Wacht am Rhein (transl. Operation Watch on the Rhine), was an offensive campaign on the Western Front during the Second World War, taking place from 16 December 1944 to 25 January 1945. It was launched through the densely forested Ardennes region of eastern Belgium and northern Luxembourg and was intended to stop Allied use of the Belgian port of Antwerp and to split the Allied lines, allowing the Germans to encircle and destroy each of the four Allied armies and force the western…', 1944, 12, 16, 1945, 1, 25, 'day', '16 December 1944 – 25 January 1945', 79, 'https://en.wikipedia.org/wiki/Battle_of_the_Bulge'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q190029', 'Kosovo War', 'The Kosovo War (Albanian: Lufta e Kosovës; Serbian: Косовски рат, Kosovski rat) was an armed conflict in Kosovo that lasted from 28 February 1998 until 11 June 1999. It was fought between the forces of the Federal Republic of Yugoslavia (FRY), which controlled Kosovo before the war, and the Kosovo Albanian separatist militia known as the Kosovo Liberation Army (KLA).', 1998, 2, NULL, 1999, 6, 11, 'month', 'February 1998 – 11 June 1999', 81, 'https://en.wikipedia.org/wiki/Kosovo_War'),
  ('Q1463967', 'Luxair Flight 9642', 'Luxair Flight 9642 was a scheduled international passenger flight from Berlin Tempelhof Airport, Germany, to Luxembourg Findel Airport, Luxembourg, operated by Luxembourg''s national airline Luxair. On 6 November 2002, the Fokker 50 operating the flight lost control and crashed onto a field during an attempted landing at the airport.', 2002, 11, 6, NULL, NULL, NULL, 'day', '6 November 2002', 50, 'https://en.wikipedia.org/wiki/Luxair_Flight_9642'),
  ('Q15991234', 'Treaty Establishing the European Stability Mechanism', 'The Treaty Establishing the European Stability Mechanism was signed by the member states of the eurozone to found the European Stability Mechanism (ESM), an international organisation located in Luxembourg, to act as a permanent source of financial assistance for member states in financial difficulty, with a maximum lending capacity of €500 billion. It replaced two earlier temporary EU funding programmes: the European Financial Stability Facility (EFSF) and the European Financial Stabilisation Mechanism (EFSM).', 2012, 2, 2, NULL, NULL, NULL, 'day', '2 February 2012', 34, 'https://en.wikipedia.org/wiki/Treaty_establishing_the_European_Stability_Mechanism'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods');
